#nullable enable
using Microsoft.Extensions.Logging;

namespace Tracto.Desktop.Actions.Handlers;

/// <summary>
/// Brings a window to the foreground by matching its title.
/// Generated by the capture engine for WindowActivate events.
///
/// Action name: navigate
/// Inputs:
///   window  (string, required) — partial window title to match
/// Outputs:
///   windowHandle (string) — hex window handle, or "0" if not found
/// </summary>
public sealed class NavigateHandler : IActionHandler
{
    private readonly ILogger<NavigateHandler> _logger;

    public string ActionName => "navigate";

    public NavigateHandler(ILogger<NavigateHandler> logger) => _logger = logger;

    public async Task<ActionResult> ExecuteAsync(ActionContext ctx)
    {
        var window = ctx.GetString("window");

        if (string.IsNullOrWhiteSpace(window))
        {
            _logger.LogWarning("navigate: no window title provided — no-op");
            return ActionResult.Ok();
        }

        var hwnd = NativeMethods.FindWindowByTitle(window);
        if (hwnd == IntPtr.Zero)
        {
            _logger.LogWarning("navigate: window '{Window}' not found", window);
            // Not fatal — the window may have been renamed or may appear shortly.
            return ActionResult.Ok(new Dictionary<string, object?> { ["windowHandle"] = "0" });
        }

        NativeMethods.SetForegroundWindow(hwnd);
        await Task.Delay(300, ctx.CancellationToken);

        _logger.LogInformation("navigate: activated window '{Window}' ({Handle:X})", window, hwnd);
        return ActionResult.Ok(new Dictionary<string, object?>
            { ["windowHandle"] = hwnd.ToString("X") });
    }
}
